    private List<CdR13FutureAssets> retained;
    @Test void actualOwnersAuthenticateEveryConsumerAndFiniteReadWindow()throws Exception{
        for(var a:actual()){var c=CdR13FutureScrollPalette.bind(a);assertSame(a.identity(),c.identity());assertEquals(a.identity().file()==CdNativeFile.R13C?6:4,c.cloudLineCounts().length());assertEquals(a.identity().file()==CdNativeFile.R13C?"010303030100":"00040303",HexFormat.of().formatHex(c.cloudLineCounts().copy()));int first=a.identity().file()==CdNativeFile.R13C?0x1F4:0x244;assertArrayEquals(new byte[]{0x41,(byte)0xF9},a.originalImage().readFile(0x184,2));assertArrayEquals(ByteBuffer.allocate(4).putInt(0x200000+first).array(),a.originalImage().readFile(0x186,4));assertArrayEquals(a.originalImage().readFile(first,2048),c.source(CdR13FutureScrollPalette.Source.PALETTE_FIRST_READS).copy());assertArrayEquals(a.originalImage().readFile(first+24,32),c.source(CdR13FutureScrollPalette.Source.PALETTE_SECOND_READS).copy());assertEquals(a.identity().file()==CdNativeFile.R13C?2:3,c.paletteCycleCount());assertEquals(2048,c.source(CdR13FutureScrollPalette.Source.PALETTE_FIRST_READS).length());assertEquals(32,c.source(CdR13FutureScrollPalette.Source.PALETTE_SECOND_READS).length());assertThrows(ReadOnlyBufferException.class,()->c.cloudLineCounts().buffer().put(0,(byte)99));assertThrows(IndexOutOfBoundsException.class,()->c.cloudLineCounts().unsignedByte(c.cloudLineCounts().length()));assertThrows(UnsupportedOperationException.class,()->c.ranges().clear());if(a.identity().file()==CdNativeFile.R13C)assertThrows(UnsupportedOperationException.class,()->c.source(CdR13FutureScrollPalette.Source.THIRD_SCRIPT));}
    }
