    @Test void twoVersusThreeNativePaletteCyclesPreserveAllUnusedTimersStepsAndWords()throws Exception{
        for(var a:actual()){var c=CdR13FutureScrollPalette.bind(a);var s=palette();var out=c.palette(s,0);assertTrue(out.completed());assertEquals(a.identity().file()==CdNativeFile.R13C?8:9,out.writes().size());assertEquals(7,out.state().timers().unsignedByte(0));assertEquals(5,out.state().timers().unsignedByte(1));assertEquals(1,out.state().steps().unsignedByte(0));assertEquals(1,out.state().steps().unsignedByte(1));int touched=c.paletteCycleCount();for(int i=touched;i<7;i++){assertEquals(s.timers().unsignedByte(i),out.state().timers().unsignedByte(i));assertEquals(s.steps().unsignedByte(i),out.state().steps().unsignedByte(i));}var expected=s.palette().copy();var first=c.source(CdR13FutureScrollPalette.Source.PALETTE_FIRST_READS);var second=c.source(CdR13FutureScrollPalette.Source.PALETTE_SECOND_READS);System.arraycopy(first.copy(),8,expected,0x6A,8);System.arraycopy(second.copy(),8,expected,0x58,8);if(touched==3){word(expected,0x44,12);assertEquals(4,out.state().timers().unsignedByte(2));}assertArrayEquals(expected,out.state().palette().copy());assertArrayEquals(bytes(128,0x11),s.palette().copy());}
    }
