    private List<CdR13FutureAssets> actual()throws Exception{if(retained!=null)return retained;String root=System.getProperty("soniccd.media.root");assumeTrue(root!=null&&!root.isBlank(),"Optional original USA media");Path cue;try(var paths=Files.list(Path.of(root).resolve("USA"))){var cues=paths.filter(p->p.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".cue")).toList();assertEquals(1,cues.size(),"configured source must contain exactly one USA CUE");cue=cues.getFirst();}try(var p=CdProgramAssets.open(cue,Optional.of(CdReleaseVariant.USA),Optional.empty())){retained=List.of(CdR13FutureAssets.fromPrograms(p,CdStagePayload.R13C.stage()),CdR13FutureAssets.fromPrograms(p,CdStagePayload.R13D.stage()));}return retained;}
    static CdR11aForegroundScroll.State foreground(int x,int y){return new CdR11aForegroundScroll.State(x,(y<<16)|0xABCD,16,16,0,0,0,0x310,0,0,0);}
    static CdR11aForegroundScroll.Input input(int x,int y,CdPlayerMovement.Bounds b){return new CdR11aForegroundScroll.Input(new CdR11aForegroundScroll.Actor(x,y,0,0,0,0),b,0,160,96,CdReleaseVariant.USA,0,320,224);}
    static byte[] bytes(int size,int seed){byte[] b=new byte[size];for(int i=0;i<size;i++)b[i]=(byte)(seed+i*13);return b;}
    static CdR11aBackgroundScroll.State background(){return new CdR11aBackgroundScroll.State(0x1111A123,0x2222B234,0x3333C345,0x4444D456,0x5555E567,0x6666F678,CdAssetBytes.copyOf(bytes(8,7)),0xA123,0xB456,0xC789,CdAssetBytes.copyOf(bytes(512,0x31)),CdAssetBytes.copyOf(bytes(512,0x53)),CdAssetBytes.copyOf(bytes(1024,0x75)),0x87654321);}
    static CdR11aBackgroundScroll.State zeroCameras(){return new CdR11aBackgroundScroll.State(0,0,0,0,0,0,CdAssetBytes.copyOf(new byte[8]),0xFFFF,0xFFFF,0xFFFF,CdAssetBytes.copyOf(bytes(512,0x31)),CdAssetBytes.copyOf(new byte[512]),CdAssetBytes.copyOf(bytes(1024,0x75)),0);}
    static CdR13FutureScrollPalette.PaletteState palette(){byte[] t=bytes(7,0x21),s=bytes(7,0x41);t[0]=t[1]=t[2]=0;s[0]=s[1]=s[2]=0;return new CdR13FutureScrollPalette.PaletteState(CdAssetBytes.copyOf(bytes(128,0x11)),CdAssetBytes.copyOf(t),CdAssetBytes.copyOf(s));}
    static void word(byte[] b,int at,int v){b[at]=(byte)(v>>>8);b[at+1]=(byte)v;}
